import logging
import uuid

from sqlalchemy import select
from sqlalchemy.orm import Session

from .models import CardModel

COLUMNS = [
    {"id": "new", "title": "New"},
    {"id": "todo", "title": "To Do"},
    {"id": "in_progress", "title": "In Progress"},
    {"id": "done", "title": "Done"},
]

# Human-readable column names for the activity log line written on each move.
COLUMN_LABELS = {"new": "New", "to_do": "To Do", "in_progress": "In Progress", "done": "Done"}

logger = logging.getLogger("boardly")


def _to_dict(card: CardModel) -> dict:
    return {
        "id": card.id,
        "title": card.title,
        "description": card.description,
        "column": card.column,
    }


class CardStore:
    """Same interface the in-memory mock had, now backed by SQLAlchemy."""

    def __init__(self, session: Session) -> None:
        self.session = session

    def list_cards(self) -> list[dict]:
        cards = self.session.scalars(select(CardModel)).all()
        return [_to_dict(c) for c in cards]

    def create(self, *, title: str, description: str, column: str) -> dict:
        card = CardModel(
            id=str(uuid.uuid4()), title=title, description=description, column=column
        )
        self.session.add(card)
        self.session.commit()
        self.session.refresh(card)
        return _to_dict(card)

    def get(self, card_id: str) -> dict | None:
        card = self.session.get(CardModel, card_id)
        return _to_dict(card) if card else None

    def update(self, card_id: str, **fields) -> dict | None:
        card = self.session.get(CardModel, card_id)
        if card is None:
            return None
        column = fields.get("column")
        if column and column != card.column:
            logger.info(
                "card moved",
                extra={"card_id": card.id, "to": COLUMN_LABELS[column]},
            )
        for key, value in fields.items():
            if value is not None:
                setattr(card, key, value)
        self.session.commit()
        self.session.refresh(card)
        return _to_dict(card)

    def delete(self, card_id: str) -> bool:
        card = self.session.get(CardModel, card_id)
        if card is None:
            return False
        self.session.delete(card)
        self.session.commit()
        return True

def ready(db: Session = Depends(get_db)):
    try:
        db.execute(text("SELECT 1"))
    except SQLAlchemyError:
        raise HTTPException(status_code=503, detail="database unavailable")
    return {"status": "ok"}


@app.get("/board", response_model=Board)
def get_board(store: CardStore = Depends(get_store)):
    return Board(
        columns=[ColumnInfo(**c) for c in COLUMNS],
        cards=[Card(**c) for c in store.list_cards()],
    )


@app.post("/cards", response_model=Card, status_code=status.HTTP_201_CREATED)
def create_card(payload: CardCreate, store: CardStore = Depends(get_store)):
    card = store.create(
        title=payload.title, description=payload.description, column=payload.column
    )
    return Card(**card)


@app.patch("/cards/{card_id}", response_model=Card)
def update_card(
    card_id: str, payload: CardUpdate, store: CardStore = Depends(get_store)
):
    card = store.update(card_id, title=payload.title, description=payload.description)
    if card is None:
        raise HTTPException(status_code=404, detail="Card not found")
    return Card(**card)


@app.patch("/cards/{card_id}/move", response_model=Card)
def move_card(card_id: str, payload: CardMove, store: CardStore = Depends(get_store)):
    card = store.update(card_id, column=payload.column)
    if card is None:
        raise HTTPException(status_code=404, detail="Card not found")
    return Card(**card)


@app.delete("/cards/{card_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_card(card_id: str, store: CardStore = Depends(get_store)):
    if not store.delete(card_id):
        raise HTTPException(status_code=404, detail="Card not found")

